window.docContents[229].resolve({"/Approximants-and-series/#chapter-2":{"contents":"These are LMLF's small interfaces around Mathlib's finite sums, filters, and little-o relation.\n\n\n\n\n\n\n\n","context":"LMLF · DLMF with Lean","header":"2. Approximants and series","id":"/Approximants-and-series/#chapter-2"},"/Elementary-Functions/___4___29-Graphics/#chapter-4-section-29":{"contents":"Source: NIST Digital Library of Mathematical Functions, §4.29, Graphics.\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions","header":"4.29. §4.29 Graphics","id":"/Elementary-Functions/___4___29-Graphics/#chapter-4-section-29"},"/Elementary-Functions/___4___48-Software/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___48-Software--___4___48-Software--___4___48_LPAR_iv_RPAR_-Lambert-W-Function":{"contents":"Effective with DLMF version 1.0.9, the reference to Lawrence et al. (2012)\nwas added to this subsection.\n\nThe Lambert W-function resources are Barry et al. (1995a), Fortran, and\nLawrence et al. (2012), C.\n\nBarry et al. (1995a) is listed as a Fortran Lambert W-function resource.\n\nLawrence et al. (2012) is listed as a C Lambert W-function resource.\n\nThe further Lambert W-function reference is Fritsch et al. (1973).\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.48 Software\u0009§4.48 Software","header":"§4.48(iv) Lambert W-Function","id":"/Elementary-Functions/___4___48-Software/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___48-Software--___4___48-Software--___4___48_LPAR_iv_RPAR_-Lambert-W-Function"}});